]$alle$::jsonb) as x(id uuid, neu_question text, question text, question_payload jsonb, title text, est integer,
                     correct_answers jsonb, acceptance jsonb, solution text, typical_errors jsonb)
  loop
    update public.tasks
       set question = r.question, question_payload = r.question_payload, input_type = 'NUMERIC', parts = '[]'::jsonb,
           title = r.title, est_duration_sec = r.est
     where id = r.id and input_type = 'MULTI_PART' and question = r.neu_question;
    if found then
      update public.task_solutions
         set correct_answers = r.correct_answers, acceptance = r.acceptance, solution = r.solution,
             typical_errors = r.typical_errors, updated_at = now()
       where task_id = r.id;
    end if;
  end loop;
end
$tr$;
